#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int findBestValue(std::vector<int>& arr, int target) {
        int lo = 0, hi = 0;
        for (int x : arr) hi = std::max(hi, x);
        auto getSum = [&](int val) {
            long long s = 0;
            for (int x : arr) s += std::min(x, val);
            return s;
        };
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (getSum(mid) < target) lo = mid + 1;
            else hi = mid;
        }
        long long s1 = getSum(lo);
        long long s2 = getSum(lo - 1);
        if (std::abs(s2 - target) <= std::abs(s1 - target)) return lo - 1;
        return lo;
    }
};

class Solution {
    public int findBestValue(int[] arr, int target) {
        int lo = 0, hi = 0;
        for (int x : arr) hi = Math.max(hi, x);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (getSum(arr, mid) < target) lo = mid + 1;
            else hi = mid;
        }
        long s1 = getSum(arr, lo);
        long s2 = getSum(arr, lo - 1);
        if (Math.abs(s2 - target) <= Math.abs(s1 - target)) return lo - 1;
        return lo;
    }
    private long getSum(int[] arr, int val) {
        long s = 0;
        for (int x : arr) s += Math.min(x, val);
        return s;
    }
}

var findBestValue = function(arr, target) {
    let lo = 0, hi = 0;
    for (const x of arr) if (x > hi) hi = x;
    const getSum = (val) => {
        let s = 0;
        for (const x of arr) s += (x < val ? x : val);
        return s;
    };
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (getSum(mid) < target) lo = mid + 1;
        else hi = mid;
    }
    const s1 = getSum(lo);
    const s2 = getSum(lo - 1);
    if (Math.abs(s2 - target) <= Math.abs(s1 - target)) return lo - 1;
    return lo;
};
